@Component("item-handler")
@ProcessingGroup("item-processing-group")
public class ItemEventHandler {
	
	// core constructor
	ItemEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateItemEvent
     */
    @EventHandler
    public void handle( CreateItemEvent event) {
        entityManager.persist(new Item(event.getItemId(), event.getItemNumber(), event.getName(), event.getStandardCost(), event.getWeight(), event.getAsSerialControlled(), event.getBusinessUnit(), event.getBoms(), event.getRoutings(), event.getSuppliers(), event.getQualitySpecifications(), event.getInventoryItems(), event.getItemType(), event.getProcurementType(), event.getUnitOfMeasure(), event.getLifecycleStatus()));
    }

    /*
     * @param	event UpdateItemEvent
     */
    @EventHandler
    public Item handle( UpdateItemEvent event) {
    	entityManager.merge(new Item(event.getItemId(), event.getItemNumber(), event.getName(), event.getStandardCost(), event.getWeight(), event.getAsSerialControlled(), event.getBusinessUnit(), event.getBoms(), event.getRoutings(), event.getSuppliers(), event.getQualitySpecifications(), event.getInventoryItems(), event.getItemType(), event.getProcurementType(), event.getUnitOfMeasure(), event.getLifecycleStatus()));
    }
    
    /*
     * @param	event DeleteItemEvent
     */
    @EventHandler
    public void on( DeleteItemEvent event) {
    	Item entity = new Item();
   
    	// ------------------------------------------
    	// apply the ItemId
    	// ------------------------------------------
    	entity.setItemId( event.getItemId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ItemRepository itemEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ItemEventHandler.class.getName());

}
